scripts/check-quality-scope.mjs:
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { promisify } from "node:util";
import { parse as parseYaml } from "yaml";

const execFileAsync = promisify(execFile);
const root = new URL("../", import.meta.url);
const SOURCE_SUFFIXES = [".js", ".jsx", ".mjs", ".cjs", ".ts", ".tsx", ".mts", ".cts"];
const FOUNDATION_PRESET = "./node_modules/@agent-teams/engineering-foundation/presets/oxlint/node.json";
const EXPECTED_SCRIPTS = {
  precheck: "node scripts/check-quality-scope.mjs",
  check: "pnpm quality:lint && pnpm renovate:validate && pnpm governance:validate && pnpm governance:cohorts:append-only && node scripts/check-community-files.mjs && node scripts/check-reviewrouter-workflow.mjs && pnpm test",
  "quality:scope": "node --test scripts/check-quality-scope.test.mjs",
  "quality:lint": "node scripts/run-quality-lint.mjs",
  "quality:check": "pnpm quality:scope && pnpm quality:lint",
  test: "node --test scripts/*.test.mjs tools/feature-module-standard/check.test.mjs",
};

const isTrackedSource = relativePath => SOURCE_SUFFIXES.some(suffix => relativePath.endsWith(suffix));

export function classifySourcePath(relativePath) {
  const normalized = relativePath.replaceAll("\\", "/");
  if (!isTrackedSource(normalized)) {return "non-source";}
  if (/^scripts\/[^/]+\.test\.mjs$/u.test(normalized) ||
      normalized === "tools/feature-module-standard/check.test.mjs") {return "test";}
  if (/^scripts\/[^/]+\.mjs$/u.test(normalized) ||
      normalized === "tools/feature-module-standard/check.mjs") {return "tooling";}
  return null;
}

export function classifyTrackedPaths(trackedPaths) {
  const classified = [];
  const unclassified = [];
  for (const relativePath of [...new Set(trackedPaths)].toSorted()) {
    const role = classifySourcePath(relativePath);
    if (role === null) {unclassified.push(relativePath);}
    else if (role !== "non-source") {classified.push({ path: relativePath, role });}
  }
  return { classified, unclassified };
}

export function deriveLintPaths(census, profile) {
  return census.classified
    .filter(entry => profile.lint.includedRoles.includes(entry.role))
    .map(entry => entry.path)
    .toSorted();
}

function assertLintPolicy(config) {
  assert.deepEqual(Object.keys(config).toSorted(), ["$schema", "extends", "options"].toSorted(),
    "Oxlint config must contain only schema, one public preset, and suppression options");
  assert.equal(config.$schema, "./node_modules/oxlint/configuration_schema.json");
  assert.deepEqual(config.extends, [FOUNDATION_PRESET], "Foundation public Node preset changed");
  assert.deepEqual(config.options, {
    reportUnusedDisableDirectives: "error",
    respectEslintDisableDirectives: false,
  });
}

function assertWorkflow(workflowText) {
  const workflow = parseYaml(workflowText);
  const steps = workflow?.jobs?.check?.steps;
  assert.ok(Array.isArray(steps), "CI check job steps are missing");
  const requiredSteps = steps.filter(step => step?.run === "pnpm check");
  assert.equal(requiredSteps.length, 1, "CI check job must contain exactly one pnpm check step");
  assert.deepEqual(requiredSteps[0], { run: "pnpm check" },
    "pnpm check step cannot be conditional or continue on error");
}

export function assertQualityAdoption({ manifest, profile, lintConfig, trackedPaths, workflow }) {
  assert.equal(manifest.devDependencies?.["@agent-teams/engineering-foundation"], "1.5.0",
    "Foundation dependency must use the exact released pin");
  assert.equal(manifest.devDependencies?.oxlint, "1.85.0", "Oxlint dependency must use the exact pin");
  for (const [name, command] of Object.entries(EXPECTED_SCRIPTS)) {
    assert.equal(manifest.scripts?.[name], command, `${name} route must stay canonical`);
  }
  assert.deepEqual(profile, {
    schemaVersion: "consumer-quality-profile-v1",
    status: "active-foundation",
    languages: ["javascript"],
    sourceRoots: {
      tooling: ["scripts/**/*.mjs", "tools/feature-module-standard/check.mjs"],
      tests: ["scripts/**/*.test.mjs", "tools/feature-module-standard/check.test.mjs"],
    },
    typedCoverage: false,
    requiredRoute: "pnpm check",
    foundation: { version: "1.5.0", publicPreset: FOUNDATION_PRESET },
    lint: { configPath: "oxlint.json", includedRoles: ["tooling"] },
    toolchain: { node: "24.18.0", pnpm: "11.18.0", oxlint: "1.85.0" },
  }, "quality profile changed");
  assertLintPolicy(lintConfig);
  assertWorkflow(workflow);
  const census = classifyTrackedPaths(trackedPaths);
  assert.deepEqual(census.unclassified, [], `unclassified executable source: ${census.unclassified.join(", ")}`);
  assert.ok(census.classified.some(entry => entry.role === "tooling"), "tooling census is empty");
  assert.ok(census.classified.some(entry => entry.role === "test"), "test census is empty");
  return census;
}

export async function readQualityAdoption(base = root) {
  const readJson = async relativePath => JSON.parse(await readFile(new URL(relativePath, base), "utf8"));
  const cwd = path.dirname(fileURLToPath(new URL("package.json", base)));
  const { stdout } = await execFileAsync("git", ["ls-files", "-z"], { cwd, encoding: "utf8" });
  return {
    manifest: await readJson("package.json"),
    profile: await readJson("docs/engineering-quality-profile.json"),
    lintConfig: await readJson("oxlint.json"),
    trackedPaths: stdout.split("\0").filter(Boolean),
    workflow: await readFile(new URL(".github/workflows/ci.yml", base), "utf8"),
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const census = assertQualityAdoption(await readQualityAdoption());
  const counts = Object.fromEntries(["tooling", "test"].map(role => [
    role,
    census.classified.filter(entry => entry.role === role).length,
  ]));
  process.stdout.write(`central quality scope verified: ${JSON.stringify(counts)}\n`);
}

scripts/check-quality-scope.test.mjs:
import assert from "node:assert/strict";
import test from "node:test";
import {
  assertQualityAdoption,
  classifySourcePath,
  classifyTrackedPaths,
  deriveLintPaths,
  readQualityAdoption,
} from "./check-quality-scope.mjs";
import { selectOxlintFiles } from "./run-quality-lint.mjs";

const accepted = await readQualityAdoption();

test("actual repository adopts the Foundation preset through the canonical route", () => {
  assertQualityAdoption(accepted);
});

test("actual tracked source census distinguishes tooling, tests, and authority data", () => {
  assert.equal(classifySourcePath("scripts/validate-governance.mjs"), "tooling");
  assert.equal(classifySourcePath("scripts/governance-policy.test.mjs"), "test");
  assert.equal(classifySourcePath("tools/feature-module-standard/check.mjs"), "tooling");
  assert.equal(classifySourcePath("tools/feature-module-standard/check.test.mjs"), "test");
  for (const authority of ["governance/policy.json", ".github/workflows/ci.yml", "GOVERNANCE.md"]) {
    assert.equal(classifySourcePath(authority), "non-source");
  }
  assert.equal(classifySourcePath("new-owner/check.mjs"), null);
});

test("actual derived tooling paths exactly match Oxlint debug selection", async () => {
  const census = assertQualityAdoption(accepted);
  const paths = deriveLintPaths(census, accepted.profile);
  assert.equal(paths.length, 21);
  assert.ok(paths.includes("scripts/docs-portable-authority-r322.mjs"));
  assert.ok(paths.includes("scripts/read-docs-portable-authority-r322.mjs"));
  assert.deepEqual(await selectOxlintFiles(paths), paths);
});

const mutations = {
  "a new unclassified executable source": value => { value.trackedPaths.push("other/new-source.ts"); },
  "a missing Foundation pin": value => { delete value.manifest.devDependencies["@agent-teams/engineering-foundation"]; },
  "a ranged Foundation pin": value => { value.manifest.devDependencies["@agent-teams/engineering-foundation"] = "^1.5.0"; },
  "a local lint rule": value => { value.lintConfig.rules = { "no-eval": "off" }; },
  "a local lint override": value => { value.lintConfig.overrides = []; },
  "a local lint ignore": value => { value.lintConfig.ignorePatterns = ["scripts/**"]; },
  "a replaced public preset": value => { value.lintConfig.extends = ["./local.json"]; },
  "a false typed claim": value => { value.profile.typedCoverage = true; },
  "a non-tooling included role": value => { value.profile.lint.includedRoles = ["test"]; },
  "a removed required route": value => { delete value.manifest.scripts.check; },
  "a no-op required route": value => { value.manifest.scripts.check = "true"; },
  "a conditional required route": value => { value.manifest.scripts.check += " || true"; },
  "a removed existing governance gate": value => { value.manifest.scripts.check = value.manifest.scripts.check.replace(" && pnpm governance:validate", ""); },
  "a missing FMS test route": value => { value.manifest.scripts.test = "node --test scripts/*.test.mjs"; },
  "authority JSON misclassified as source": value => { value.trackedPaths.push("governance/authority.ts"); },
  "a missing CI route": value => { value.workflow = value.workflow.replace("- run: pnpm check", "- run: pnpm test"); },
  "a conditional CI route": value => { value.workflow = value.workflow.replace("- run: pnpm check", "- if: always()\n        run: pnpm check"); },
  "a continue-on-error CI route": value => { value.workflow = value.workflow.replace("- run: pnpm check", "- run: pnpm check\n        continue-on-error: true"); },
};

for (const [name, mutate] of Object.entries(mutations)) {
  test(`quality adoption rejects ${name}`, () => {
    const value = structuredClone(accepted);
    mutate(value);
    assert.throws(() => assertQualityAdoption(value), assert.AssertionError);
  });
}

test("a changed derived tooling set differs from the actual Oxlint selection", async () => {
  const census = classifyTrackedPaths(accepted.trackedPaths);
  const paths = deriveLintPaths(census, accepted.profile);
  await assert.rejects(() => selectOxlintFiles([...paths, "README.md"]),
    /selected files differ/u);
});

.github/workflows/docs-cohort-append-onl:
name: Qualified Docs Cohort Trusted Validation

on:
  pull_request_target:
    types: [opened, synchronize, reopened, edited]

permissions:
  actions: read
  checks: read
  contents: read
  pull-requests: read

jobs:
  trusted-validation:
    name: trusted-validation
    runs-on: ubuntu-24.04
    timeout-minutes: 8
    steps:
      - id: materialize
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        with:
          script: |
            const fs = require("node:fs/promises");
            const path = require("node:path");
            const pull = context.payload.pull_request;
            const registryPath = "governance/docs-qualified-cohorts.json";
            const allowedRegistryPath = "governance/docs-qualified-cohorts.json";
            const allowedEvidence = /^governance\/evidence\/docs-cohorts\/[a-z0-9][a-z0-9._/-]*\.(?:json|md)$/;
            const allowedRuntimeClosure = /^governance\/docs-runtime-closures\/sha256-[0-9a-f]{64}\.json$/;
            const authorityPaths = new Set([
              ".github/workflows/docs-cohort-append-only.yml",
              ".github/workflows/docs-admission-evidence.yml",
              ".github/workflows/docs-protocol-check.yml",
              ".node-version",
              ".npmrc",
              "governance/docs-protocol-exceptions.schema.json",
              "governance/docs-protocol-policy.schema.json",
              "governance/docs-qualified-cohorts.schema.json",
              "package.json",
              "pnpm-lock.yaml",
              "pnpm-workspace.yaml",
              "renovate-config.json",
              "renovate.json",
              "scripts/check-cohort-append-only.mjs",
              "scripts/check-cohort-emergency-append.mjs",
              "scripts/check-community-files.mjs",
              "scripts/docs-cohort-policy.mjs",
              "scripts/governance-policy.mjs",
              "scripts/validate-governance.mjs",
              "scripts/verify-docs-cohort-evidence.mjs",
              "scripts/verify-docs-admission-change.mjs",
              "scripts/verify-docs-consumer-gate.mjs"
            ]);
            const installAuthorityNames = new Set([
              ".npmrc", ".pnpmfile.cjs", "package.json", "pnpm-lock.yaml", "pnpm-workspace.yaml"
            ]);
            const isInstallAuthority = (entry) =>
              installAuthorityNames.has(entry.split("/").at(-1));
            const changedFileCap = 3000;
            if (!Number.isSafeInteger(pull.changed_files) || pull.changed_files < 1 ||
                pull.changed_files > changedFileCap) {
              core.setFailed(`PR changed_files must be within 1..${changedFileCap}.`);
              return;
            }
            const changed = await github.paginate(github.rest.pulls.listFiles, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: pull.number,
              per_page: 100
            });
            if (changed.length !== pull.changed_files ||
                new Set(changed.map(({ filename }) => filename)).size !== changed.length) {
              core.setFailed("Paginated PR file evidence is incomplete or contains duplicate filenames.");
              return;
            }
            const changedAuthority = changed.filter(({ filename, previous_filename: prior }) =>
              [filename, prior].filter(Boolean).some((entry) =>
                authorityPaths.has(entry) || isInstallAuthority(entry)));
            if (changedAuthority.length > 0) {
              core.setFailed(`Authority files require a separately staged successor check and ruleset cutover; they cannot pass or bypass this base-owned check: ${changedAuthority.map(({ filename, previous_filename: prior }) => prior ? prior + " -> " + filename : filename).join(", ")}`);
              return;
            }
            const changesRegistry = changed.some(({ filename, previous_filename: prior }) =>
              filename === registryPath || prior === registryPath);
            if (!changesRegistry) {
              core.setOutput("mode", "noop");
              return;
            }
            const controller = await github.rest.repos.get({
              owner: context.repo.owner,
              repo: context.repo.repo
            });
            if (pull.base.ref !== controller.data.default_branch) {
              core.setFailed("Cohort lifecycle PR base must be the live controller default branch.");
              return;
            }
            const branch = await github.rest.repos.getBranch({
              owner: context.repo.owner,
              repo: context.repo.repo,
              branch: controller.data.default_branch
            });
            if (branch.data.commit.sha !== pull.base.sha) {
              core.setFailed("PR base is stale; update it before appending lifecycle history.");
              return;
            }
            const forbidden = changed.filter((file) => {
              const paths = [file.filename, file.previous_filename].filter(Boolean);
              if (paths.some((entry) => entry !== allowedRegistryPath &&
                  !allowedEvidence.test(entry) && !allowedRuntimeClosure.test(entry))) return true;
              if (file.filename === allowedRegistryPath) return !["added", "modified"].includes(file.status);
              return file.status !== "added" || file.previous_filename !== undefined;
            });
            if (forbidden.length > 0) {
              core.setFailed(`Lifecycle PRs may change only the registry and new inert Cohort evidence. Renames, deletes, executable authority, dependencies, schemas, policy, workflows, and scripts require a separate PR: ${forbidden.map(({ filename, previous_filename: prior }) => prior ? prior + " -> " + filename : filename).join(", ")}`);
              return;
            }
            async function load(ref, allowMissing = false) {
              try {
                const response = await github.rest.repos.getContent({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  path: registryPath,
                  ref
                });
                if (Array.isArray(response.data) || response.data.type !== "file" ||
                    response.data.encoding !== "base64") {
                  throw new Error("Qualified Docs Cohort registry is not one base64-encoded file.");
                }
                return Buffer.from(response.data.content, "base64").toString("utf8");
              } catch (error) {
                if (allowMissing && error.status === 404) return undefined;
                throw error;
              }
            }
            const head = await load(pull.head.sha);
            const baseSource = await load(pull.base.sha, true);
            const base = baseSource ?? (() => {
              const bootstrap = JSON.parse(head);
              return JSON.stringify({ ...bootstrap, cohorts: [], events: [] });
            })();
            let mode = "full";
            try {
              const baseValue = JSON.parse(base);
              const headValue = JSON.parse(head);
              const baseCohorts = Array.isArray(baseValue.cohorts) ? baseValue.cohorts : [];
              const headCohorts = Array.isArray(headValue.cohorts) ? headValue.cohorts : [];
              const baseClosurePaths = new Set(baseCohorts.map((entry) =>
                entry.runtime_closure?.projection_path).filter(Boolean));
              const requiredNewClosures = new Set(headCohorts.slice(baseCohorts.length)
                .map((entry) => entry.runtime_closure?.projection_path).filter((entry) =>
                  typeof entry === "string" && !baseClosurePaths.has(entry)));
              const addedClosures = new Set(changed.filter(({ filename, status, previous_filename: prior }) =>
                allowedRuntimeClosure.test(filename) && status === "added" && prior === undefined)
                .map(({ filename }) => filename));
              if (JSON.stringify([...requiredNewClosures].sort()) !==
                  JSON.stringify([...addedClosures].sort())) {
                core.setFailed("New runtime closure evidence must be create-only and referenced exactly by an appended Cohort record.");
                return;
              }
              const { events: baseEvents, ...baseAuthority } = baseValue;
              const { events: headEvents, ...headAuthority } = headValue;
              const appended = Array.isArray(baseEvents) && Array.isArray(headEvents)
                ? headEvents.slice(baseEvents.length)
                : [];
              if (JSON.stringify(baseAuthority) === JSON.stringify(headAuthority) &&
                  headEvents.length > baseEvents.length &&
                  JSON.stringify(headEvents.slice(0, baseEvents.length)) === JSON.stringify(baseEvents) &&
                  appended.every(({ state }) => ["SUPPORT_ENDED", "SUSPENDED", "WITHDRAWN"].includes(state))) {
                mode = "emergency";
              }
            } catch {
              mode = "full";
            }
            const basePath = path.join(process.env.RUNNER_TEMP, "docs-cohort-base.json");
            const headPath = path.join(process.env.RUNNER_TEMP, "docs-cohort-head.json");
            const changedFilesPath = path.join(process.env.RUNNER_TEMP, "docs-cohort-changed-files.json");
            await Promise.all([
              fs.writeFile(basePath, base, { flag: "wx" }),
              fs.writeFile(headPath, head, { flag: "wx" }),
              fs.writeFile(changedFilesPath, JSON.stringify(changed), { flag: "wx" })
            ]);
            core.setOutput("base-path", basePath);
            core.setOutput("head-path", headPath);
            core.setOutput("mode", mode);
            core.setOutput("changed-files-path", changedFilesPath);
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        if: steps.materialize.outputs.mode != 'noop'
        with:
          ref: ${{ github.event.pull_request.base.sha }}
          persist-credentials: false
      - id: pnpm-v1
        uses: pnpm/action-setup@008330803749db0355799c700092d9a85fd074e9 # v6.0.9
        if: steps.materialize.outputs.mode == 'full'
        with:
          version: 11.18.0
          dest: ${{ runner.temp }}/docs-cohort-pnpm-v1
          run_install: false
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        if: steps.materialize.outputs.mode == 'full'
        with:
          node-version: 24.18.0
          cache: pnpm
      - id: pnpm-v2
        uses: pnpm/action-setup@008330803749db0355799c700092d9a85fd074e9 # v6.0.9
        if: steps.materialize.outputs.mode == 'full'
        with:
          version: 11.20.0
          dest: ${{ runner.temp }}/docs-cohort-pnpm-v2
          package_json_file: governance/docs-qualified-cohorts.schema.json
          run_install: false
      - name: Verify trusted package-manager binaries
        if: steps.materialize.outputs.mode == 'full'
        env:
          DOCS_COHORT_PNPM_V1_BIN: ${{ steps.pnpm-v1.outputs.bin_dest }}/pnpm
          DOCS_COHORT_PNPM_V2_BIN: ${{ steps.pnpm-v2.outputs.bin_dest }}/pnpm
        run: |
          test "$(cd "$RUNNER_TEMP" && "$DOCS_COHORT_PNPM_V1_BIN" --version)" = "11.18.0"
          test "$(cd "$RUNNER_TEMP" && "$DOCS_COHORT_PNPM_V2_BIN" --version)" = "11.20.0"
          test "$DOCS_COHORT_PNPM_V1_BIN" != "$DOCS_COHORT_PNPM_V2_BIN"
      - name: Install trusted base dependencies with Cohort v1 pnpm
        if: steps.materialize.outputs.mode == 'full'
        env:
          DOCS_COHORT_PNPM_V1_BIN: ${{ steps.pnpm-v1.outputs.bin_dest }}/pnpm
        run: >-
          "$DOCS_COHORT_PNPM_V1_BIN" install --frozen-lockfile --ignore-scripts
          --ignore-pnpmfile
      - name: Validate negative emergency append without network dependencies
        if: steps.materialize.outputs.mode == 'emergency'
        env:
          DOCS_COHORT_BASE_PATH: ${{ steps.materialize.outputs.base-path }}
          DOCS_COHORT_CURRENT_PATH: ${{ steps.materialize.outputs.head-path }}
          DOCS_COHORT_EVIDENCE_REF: ${{ github.event.pull_request.head.sha }}
          DOCS_COHORT_CHANGED_FILES_PATH: ${{ steps.materialize.outputs.changed-files-path }}
        run: node scripts/check-cohort-emergency-append.mjs
      - name: Validate untrusted head with trusted base code
        if: steps.materialize.outputs.mode == 'full'
        env:
          DOCS_COHORT_BASE_PATH: ${{ steps.materialize.outputs.base-path }}
          DOCS_COHORT_CURRENT_PATH: ${{ steps.materialize.outputs.head-path }}
        run: node scripts/check-cohort-append-only.mjs
      - name: Verify live evidence for every appended Cohort record or event
        if: steps.materialize.outputs.mode == 'full'
        env:
          GH_TOKEN: ${{ secrets.DOCS_GOVERNANCE_READ_TOKEN || github.token }}
          DOCS_COHORT_BASE_PATH: ${{ steps.materialize.outputs.base-path }}
          DOCS_COHORT_CURRENT_PATH: ${{ steps.materialize.outputs.head-path }}
          DOCS_COHORT_EVIDENCE_REF: ${{ github.event.pull_request.head.sha }}
          DOCS_COHORT_PNPM_V1_BIN: ${{ steps.pnpm-v1.outputs.bin_dest }}/pnpm
          DOCS_COHORT_PNPM_V2_BIN: ${{ steps.pnpm-v2.outputs.bin_dest }}/pnpm
        run: >-
          node scripts/verify-docs-cohort-evidence.mjs
          --registry "$DOCS_COHORT_CURRENT_PATH"
          --schema governance/docs-qualified-cohorts.schema.json
          --changed-from "$DOCS_COHORT_BASE_PATH"

scripts/check-reviewrouter-workflow.mjs:
import { readFile } from "node:fs/promises";

import { parse } from "yaml";

const reviewPath = ".github/workflows/reviewrouter-codex.yml";
const interactionPath = ".github/workflows/reviewrouter-interaction.yml";
const reviewCommit = "8a0a31ae1d92c89466c8a939272a1e333e88c5a0";
const interactionCommit = "6b35091c824b1d4d5ee6bf8316121ed08d3e4861";
const reviewSecret =
  "REVIEWROUTER_CODEX_AUTH_JSON_R1316243981_P2e7c56bda356e46d_E3_805e1404efa0ee03613cabc31b18f2a3";
const reviewSecretMatch =
  /_E([1-9][0-9]*)_([a-f0-9]{32})$/.exec(reviewSecret);
if (!reviewSecretMatch) {
  throw new Error("reviewSecret must use the versioned namespace format.");
}
const [, reviewEpoch, reviewNamespace] = reviewSecretMatch;
const expectedReviewUses =
  `777genius/review-router/.github/workflows/reviewrouter-t0-reusable.yml@${reviewCommit}`;
const expectedInteractionUses =
  `777genius/review-router/.github/workflows/reviewrouter-interaction-reusable.yml@${interactionCommit}`;

function assert(condition, message) {
  if (!condition) {
    throw new Error(message);
  }
}

function samePermissions(actual, expected) {
  return (
    JSON.stringify(Object.entries(actual ?? {}).toSorted()) ===
    JSON.stringify(Object.entries(expected).toSorted())
  );
}

async function loadWorkflow(path) {
  const source = await readFile(path, "utf8");
  return { source, workflow: parse(source) };
}

const review = await loadWorkflow(reviewPath);
const interaction = await loadWorkflow(interactionPath);

assert(
  review.workflow.on?.pull_request_target,
  `${reviewPath} must use pull_request_target for the versioned V4 secret namespace.`,
);
assert(
  review.workflow.on?.pull_request === undefined,
  `${reviewPath} must not retain the legacy pull_request trigger.`,
);
assert(
  review.workflow.on?.workflow_dispatch === undefined,
  `${reviewPath} must not enable workflow_dispatch for the client-triggered schema.`,
);
assert(
  samePermissions(review.workflow.permissions, {}),
  `${reviewPath} must deny root token permissions.`,
);
assert(
  review.workflow.name ===
    `ReviewRouter Codex OAuth [namespace=sns_${reviewNamespace};epoch=${reviewEpoch};secret=${reviewSecret}]`,
  `${reviewPath} must attest the exact versioned namespace in its name.`,
);

const reviewJob = review.workflow.jobs?.["codex-review"];
assert(reviewJob?.uses === expectedReviewUses, `${reviewPath} must use the immutable T0 workflow.`);
assert(
  reviewJob.with?.runtime_ref === reviewCommit,
  "codex-review must pin the reusable workflow and runtime to the same commit.",
);
assert(
  samePermissions(reviewJob.permissions, {
    contents: "read",
    "pull-requests": "read",
    "id-token": "write",
  }),
  "codex-review must keep the Actions token read-only and grant only OIDC write.",
);
assert(reviewJob.with?.workflow_schema_version === 4, "codex-review must use workflow schema 4.");
assert(
  reviewJob.if ===
    "${{ github.event_name == 'pull_request_target' && github.event.pull_request.head.repo.full_name == github.repository && github.event.pull_request.user.type != 'Bot' && (github.event.pull_request.draft == false || vars.REVIEW_ROUTER_REVIEW_DRAFTS == 'true') }}",
  "codex-review must preserve the same-repository, non-bot V4 event filter.",
);
assert(
  reviewJob.with?.provider_instance_id === "codex-rotating:1316243981",
  "codex-review must bind the .github repository provider identity.",
);
assert(
  reviewJob.secrets?.CODEX_AUTH_JSON ===
    `\${{ secrets.${reviewSecret} }}`,
  "codex-review must use the exact versioned rotating provider secret.",
);

const refreshJob = review.workflow.jobs?.["codex-refresh"];
const refreshStep = refreshJob?.steps?.[0];
assert(
  samePermissions(refreshJob?.permissions, { "id-token": "write" }),
  "codex-refresh must grant only OIDC write.",
);
assert(
  refreshStep?.uses === `777genius/review-router@${reviewCommit}`,
  "codex-refresh must pin the same immutable ReviewRouter runtime commit.",
);
assert(
  refreshStep?.with?.["workflow-schema-version"] === "4",
  "codex-refresh must use workflow schema 4.",
);
assert(
  refreshStep?.with?.["provider-instance-id"] === "codex-rotating:1316243981",
  "codex-refresh must bind the .github repository provider identity.",
);
assert(
  refreshStep?.with?.["auth-json"] === `\${{ secrets.${reviewSecret} }}`,
  "codex-refresh must use the exact versioned rotating provider secret.",
);

assert(
  samePermissions(interaction.workflow.permissions, {}),
  `${interactionPath} must deny root token permissions.`,
);
assert(
  JSON.stringify(interaction.workflow.on?.pull_request_review_comment?.types) ===
      JSON.stringify(["created", "edited"]) &&
    JSON.stringify(interaction.workflow.on?.issue_comment?.types) ===
      JSON.stringify(["created", "edited"]) &&
    interaction.workflow.on?.workflow_dispatch !== undefined,
  `${interactionPath} must preserve review-comment, PR-comment, and manual events.`,
);
const interactionJob = interaction.workflow.jobs?.interaction;
assert(
  interactionJob?.if ===
    "${{ github.event_name == 'workflow_dispatch' || ((github.event_name != 'issue_comment' || github.event.issue.pull_request) && github.event.comment.user.type != 'Bot') }}",
  "interaction must preserve the PR-only and non-bot event filter.",
);
assert(
  interactionJob?.uses === expectedInteractionUses,
  `${interactionPath} must call the immutable upstream interaction workflow.`,
);
assert(
  samePermissions(interactionJob?.permissions, {
    actions: "write",
    contents: "read",
    issues: "read",
    "pull-requests": "read",
    "id-token": "write",
  }),
  "interaction must grant only the permissions required for App publication, OIDC, and exact-run reruns.",
);
assert(
  interactionJob?.with?.runtime_ref === interactionCommit,
  "interaction must pin the reusable workflow and runtime to the same commit.",
);
assert(
  interactionJob?.with?.api_url === "https://api.reviewrouter.site" &&
    interactionJob?.with?.runtime_config_mode === "oidc" &&
    interactionJob?.with?.review_workflow_file === "reviewrouter-codex.yml",
  "interaction must preserve its API, OIDC, and review-workflow contract.",
);
assert(
  interactionJob?.with?.discussion_mode ===
    "${{ vars.REVIEW_ROUTER_DISCUSSION_MODE || 'off' }}" &&
    interactionJob?.with?.discussion_model ===
      "${{ vars.REVIEW_CODEX_MODEL || 'gpt-5.5' }}" &&
    interactionJob?.with?.discussion_reasoning_effort ===
      "${{ vars.REVIEW_CODEX_EFFORT || 'xhigh' }}" &&
    interactionJob?.with?.discussion_max_per_pr ===
      "${{ vars.REVIEW_ROUTER_DISCUSSION_MAX_PER_PR || '20' }}" &&
    interactionJob?.with?.discussion_max_per_thread ===
      "${{ vars.REVIEW_ROUTER_DISCUSSION_MAX_PER_THREAD || '5' }}" &&
    interactionJob?.with?.discussion_timeout_seconds ===
      "${{ vars.REVIEW_ROUTER_DISCUSSION_TIMEOUT_SECONDS || '60' }}",
  "interaction must preserve all discussion variable mappings.",
);
assert(
  samePermissions(interactionJob?.secrets, {
    REVIEW_ROUTER_LEDGER_KEY: "${{ secrets.REVIEW_ROUTER_LEDGER_KEY }}",
    CODEX_AUTH_JSON: "${{ secrets.REVIEWROUTER_CODEX_AUTH_JSON }}",
  }),
  "interaction must preserve only the required secret mappings.",
);
assert(
  interactionJob?.steps === undefined &&
    interactionJob?.["runs-on"] === undefined &&
    interactionJob?.env === undefined,
  "interaction must remain a thin reusable-workflow caller.",
);

for (const legacyMarker of [
  "mode: codex-oauth-rotating",
  "REVIEWROUTER_COMMENT_TOKEN_MODE: github-token",
  "actions/checkout@",
  "actions/setup-node@",
  ".reviewrouter-runtime",
  "npm install -g",
]) {
  assert(
    !review.source.includes(legacyMarker) && !interaction.source.includes(legacyMarker),
    `Legacy ReviewRouter marker is forbidden: ${legacyMarker}`,
  );
}

console.log("ReviewRouter workflows verified: pinned thin callers with least-privilege tokens.");

.github/workflows/reviewrouter-interacti:
name: ReviewRouter Interaction

on:
  pull_request_review_comment:
    types: [created, edited]
  issue_comment:
    types: [created, edited]
  workflow_dispatch:

permissions: {}

jobs:
  interaction:
    name: interaction
    if: ${{ github.event_name == 'workflow_dispatch' || ((github.event_name != 'issue_comment' || github.event.issue.pull_request) && github.event.comment.user.type != 'Bot') }}
    permissions:
      actions: write
      contents: read
      issues: read
      pull-requests: read
      id-token: write
    uses: 777genius/review-router/.github/workflows/reviewrouter-interaction-reusable.yml@6b35091c824b1d4d5ee6bf8316121ed08d3e4861
    with:
